<?php
require dirname(__DIR__).'/backend/app/bootstrap.php';$user=require_permission('view_staff');$id=positive_id($_GET,'id');$row=staff_record($id);$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){
    require_permission('manage_staff');verify_csrf();
    try{$note=input('history_note',10000);if($note==='')throw new InvalidArgumentException('Enter a history note.');$effective=date_value(input('effective_date',10),true);if($effective>date('Y-m-d'))throw new InvalidArgumentException('History notes cannot be future-dated.');query("INSERT INTO staff_history(staff_id,actor_id,event_type,effective_date,notes) VALUES(?,?,'note',?,?)",[$id,$user['id'],$effective,$note]);flash('History note added.');redirect('employee.php?id='.$id);}catch(InvalidArgumentException $e){$error=$e->getMessage();}
}
$total=(int)query('SELECT COUNT(*) FROM staff_history WHERE staff_id=?',[$id])->fetchColumn();$page=page_number($total);$entries=query('SELECT h.*,u.full_name actor_name FROM staff_history h JOIN users u ON u.id=h.actor_id WHERE staff_id=? ORDER BY effective_date DESC,h.id DESC LIMIT 25 OFFSET '.(($page-1)*25),[$id])->fetchAll();
$tickets=user_can('view_all_tickets')?query('SELECT id,ticket_number,subject,status FROM tickets WHERE staff_id=? AND deleted_at IS NULL ORDER BY id DESC LIMIT 5',[$id])->fetchAll():[];
page_start('Employee profile',$user);?><a class="back-link" href="staff.php">← Staff directory</a><?php error_notice($error);?><section class="panel"><div class="profile-head"><div><p class="eyebrow"><?=e($row['employee_code'])?></p><h2><?=e($row['full_name'])?></h2><span class="badge <?=e($row['employment_status'])?>"><?=e(STAFF_STATUSES[$row['employment_status']])?></span></div><div class="actions"><?php if(user_can('create_tickets')):?><a class="button button-secondary" href="create-ticket.php?staff_id=<?=$id?>">Create ticket</a><?php endif;if(user_can('manage_staff')):?><a class="button" href="employee-form.php?id=<?=$id?>">Edit profile</a><?php endif;?></div></div><dl class="profile-facts"><?php foreach(['position'=>'Position','shift_schedule'=>'Shift schedule','tl_name'=>'Team leader','department_name'=>'Department','team_label'=>'Team','start_date'=>'Started','exit_date'=>'Exited'] as $key=>$label):?><div><dt><?=$label?></dt><dd><?=e($row[$key]?:'—')?></dd></div><?php endforeach;?></dl><?php if($row['notes']):?><p class="preserve-lines"><?=e($row['notes'])?></p><?php endif;?></section><div class="split"><section class="panel"><div class="section-head"><h2>Staff history</h2><?php if(user_can('export_staff')):?><a class="button button-secondary" href="export.php?type=history&amp;staff_id=<?=$id?>">Export history</a><?php endif;?></div><?php foreach($entries as $entry):?><article class="timeline-item"><h3><?=e(ucfirst($entry['event_type']))?> · <?=e($entry['effective_date'])?></h3><small>Recorded by <?=e($entry['actor_name'])?> on <?=e($entry['created_at'])?></small><p><?=e($entry['notes'])?></p><?php $changes=history_changes($entry);if($changes):?><details <?=$entry['event_type']==='updated'?'open':''?>><summary>Profile changes</summary><ul class="changes"><?php foreach($changes as $change):?><li><?=e($change)?></li><?php endforeach;?></ul></details><?php endif;?></article><?php endforeach;if(!$entries):?><p class="empty">No history has been recorded.</p><?php endif;pagination($total,$page);?></section><div><?php if(user_can('manage_staff')):?><section class="panel"><h2>Add a history note</h2><p class="muted">Record an earlier event or context. Notes do not change current profile details.</p><form method="post"><?php csrf_field();?><label>Effective date<input name="effective_date" type="date" required max="<?=date('Y-m-d')?>" value="<?=e(request_string($_POST,'effective_date')?:date('Y-m-d'))?>"></label><label>Note<textarea name="history_note" required maxlength="10000" rows="4"><?=e(request_string($_POST,'history_note'))?></textarea></label><div class="form-footer"><button class="button">Add note</button></div></form></section><?php endif;if(user_can('view_all_tickets')):?><section class="panel"><h2>Recent tickets</h2><?php foreach($tickets as $ticket):?><p><a href="ticket.php?id=<?=$ticket['id']?>"><?=e($ticket['ticket_number'])?> · <?=e($ticket['subject'])?></a></p><?php endforeach;if(!$tickets):?><p class="muted">No tickets linked to this employee.</p><?php endif;?><a href="index.php?staff_id=<?=$id?>">View all linked tickets →</a></section><?php endif;?></div></div><?php page_end();
